#!/usr/bin/env python3
"""Render the production composer menu with isolated synthetic session storage."""
from pathlib import Path
import re
root=Path(__file__).resolve().parents[2];web=root/'internal/server/web';source=(web/'app.js').read_text()
def function(name):
 start=re.search(r'^function '+name+r'\(',source,re.M).start();line=source[start:source.index('\n',start)]
 return line if line.endswith('}') else source[start:source.index('\n}',start)+2]
functions='\n'.join(function(name) for name in ['sessionModelPreferences','activeModel','profileName','modelProviderName','refreshStrategyUI','strategyMenuOption'])
css='\n'.join((web/p).read_text() for p in ['themes/dark/tokens.css','themes/light/tokens.css','style.css','macos.css','experience.css','sanctum.css','conversation.css'])
html='''<!doctype html><html data-theme="dark"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Session model selection</title><style>'''+css+'''body{display:block;padding:28px;height:auto;overflow:auto}.fixture-tools{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0}.fixture-tools button{padding:8px 12px;border:1px solid var(--line);border-radius:8px}.fixture{max-width:920px}.fixture .strategy-picker{display:block}.strategy-menu{position:static;margin-top:12px;width:100%;max-width:100%}.report{font:12px/1.8 monospace;white-space:pre-wrap}.strategy-button{max-width:100%}</style><h2>Session model selection</h2><p>Production menu and selection module; mock session saves only. No real model calls.</p><div class="fixture-tools"><button id="a">Chat A</button><button id="b">Chat B</button><button id="draft">New draft</button><button id="theme">Light / dark</button><button id="narrow">Narrow / wide</button></div><div class="fixture"><div class="report" id="report"></div><div class="strategy-picker"><button id="strategy-button" class="strategy-button" aria-expanded="true"><span id="strategy-label"></span></button><div id="strategy-menu" class="strategy-menu" role="menu"></div></div><p id="model-name"></p><p id="notice"></p></div><script>'''+(web/'session-model-selection.js').read_text()+'''</script><script>
const $=id=>document.getElementById(id),el=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls||'';if(text!=null)e.textContent=text;return e;},t=(s,...args)=>s.replace(/\\{(\\d+)\\}/g,(_,n)=>args[n]);
const choices={a:{id:'a',modelSelection:{strategy:'auto',profile:'default',model:'model-a',reasoningEffort:'auto'},modelSelectionRevision:0},b:{id:'b',modelSelection:{strategy:'manual',profile:'precise',model:'model-b',reasoningEffort:'high'},modelSelectionRevision:0}};
const state={session:structuredClone(choices.a),config:{configured:true,workspaceId:'fixture',activeModel:'model-a',model:'model-a',reasoningEffort:'auto',models:[{id:'model-a',name:'Model A',providerId:'a',contextWindow:65536},{id:'model-b',name:'Model B',providerId:'b',contextWindow:131072}],modelProviders:[{id:'a',name:'Provider A'},{id:'b',name:'Provider B'}]},profiles:{strategy:'auto',activeProfile:'default',profiles:[{id:'default',name:'Default',system:true},{id:'precise',name:'Precise',system:true}]} };
const action=fn=>async(...args)=>{try{await fn(...args)}catch(e){$('notice').textContent=e.message}},recoveryScope=()=> 'fixture',composerAutoReview=()=>false,setComposerAutoReview=async()=>{},profilesManager={flush(){throw Error('Unexpected global profile save');}},toast=text=>{$('notice').textContent=text;},openSettings=()=>{},closeStrategyMenu=()=>{$('strategy-menu').classList.add('hidden');$('strategy-button').setAttribute('aria-expanded','false');};
async function api(path,options){if(!path.endsWith('/model-selection'))throw Error('Unexpected global/API write');const id=path.split('/')[2],body=JSON.parse(options.body);if(body.revision!==choices[id].modelSelectionRevision){const e=Error('Conflict');e.status=409;throw e;}const {revision,...selection}=body;choices[id].modelSelection=selection;choices[id].modelSelectionRevision++;return {modelSelection:selection,revision:choices[id].modelSelectionRevision};}
'''+functions+'''
function report(){const choice=sessionModelPreferences();$('report').textContent='chat='+(state.session?.id||'draft')+' | strategy='+choice.strategy+' / '+choice.profile+' | model='+choice.model+' | reasoning='+choice.reasoningEffort+'\\nGlobal defaults unchanged: '+state.config.activeModel+' / '+state.profiles.strategy+' / '+state.config.reasoningEffort;}
window.AideSessionModelSelection.install({state,api,changed(){refreshStrategyUI();report();}});
for(const id of ['a','b','draft'])$(id).onclick=()=>{state.session=id==='draft'?null:structuredClone(choices[id]);refreshStrategyUI();report();$('strategy-menu').classList.remove('hidden');};
$('strategy-button').onclick=()=>{$('strategy-menu').classList.toggle('hidden');};
$('theme').onclick=()=>{document.documentElement.dataset.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';};
$('narrow').onclick=()=>{document.querySelector('.fixture').style.maxWidth='390px';};refreshStrategyUI();report();
</script></html>'''
p=root/'.agent-state/session-model-selection/preview.html';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(html);print(p)
